using System;using System.Linq;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;
namespace CTXD.Client.Features.Social { public sealed class KfzbPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;KfzbView _view;GeneralRosterResponse _roster;int[] _selected=Array.Empty<int>();public static KfzbPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("KfzbPanel");go.transform.SetParent(host,false);var p=go.AddComponent<KfzbPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var b=LegacyUiFactory.Panel(transform,"KfzbBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.84f));_window=LegacyUiFactory.PixelPanel(b,"KfzbWindow",220,55,840,640,new Color(.05f,.025f,.012f,1));}async Task Refresh(){try{_view=await _api.GetKfzbAsync();_roster=await _api.GetGeneralsAsync();Draw();}catch(Exception e){_status(e.Message);Destroy(gameObject);}}void Draw(){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"KFZB - SEASON "+_view.seasonNo,22,TextAnchor.MiddleCenter,new Color(1,.75f,.25f),240,12,360,35);LegacyUiFactory.PixelButton(_window,"Close",750,16,65,27,()=>Destroy(gameObject));LegacyUiFactory.PixelLabel(_window,"State "+_view.globalState+"   W "+_view.wins+" / L "+_view.losses+(_view.eliminated?"   ELIMINATED":""),16,TextAnchor.MiddleCenter,_view.eliminated?new Color(1,.35f,.25f):Color.white,120,55,600,30);if(!_view.signed&&_view.globalState==20)LegacyUiFactory.PixelButton(_window,"Sign up with all generals",450,105,270,36,()=>Signup());var y=105;foreach(var g in (_roster?.military??Array.Empty<GeneralView>()).Take(9)){var id=g.id;var selected=_selected.Contains(id);LegacyUiFactory.PixelButton(_window,(selected?"* ":"")+g.name+" Lv"+g.level,45,y,320,30,()=>{_selected=selected?_selected.Where(x=>x!=id).ToArray():_selected.Append(id).ToArray();Draw();});y+=37;}if(_view.signed&&!_view.eliminated)LegacyUiFactory.PixelButton(_window,"Sync selected formation",450,150,270,34,()=>Sync());if(_view.match!=null){var m=_view.match;LegacyUiFactory.PixelLabel(_window,"Phase "+m.phase+"  Layer "+m.layer+"  Round "+m.round,17,TextAnchor.MiddleCenter,Color.white,430,220,330,30);LegacyUiFactory.PixelLabel(_window,"Opponent "+m.opponentPlayerId,15,TextAnchor.MiddleCenter,Color.gray,430,255,330,28);if(m.battleId>0&&m.state==1){var battle=m.battleId;LegacyUiFactory.PixelButton(_window,"Resume battle",480,300,230,38,async()=>{try{await _api.GetBattleAsync(battle);_status("KFZB battle "+battle+" ready");}catch(Exception e){_status(e.Message);}});}else if(m.state==2)LegacyUiFactory.PixelLabel(_window,"Winner "+m.winnerPlayerId,17,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),470,300,250,35);}}async void Signup(){try{_view=await _api.SignupKfzbAsync();_status("KFZB signup complete");await Refresh();}catch(Exception e){_status(e.Message);}}async void Sync(){try{if(_selected.Length==0)throw new Exception("Select at least one general");_view=await _api.SyncKfzbAsync(_selected);_status("KFZB formation synchronized");await Refresh();}catch(Exception e){_status(e.Message);}}} }
